// O(n): a single pass
int Sum(int[] a) {
    int s = 0;
    foreach (int x in a) s += x;
    return s;
}

// O(n²): all pairs i < j — n(n − 1)/2 comparisons
int CountEqualPairs(int[] a) {
    int c = 0;
    for (int i = 0; i < a.Length; i++)
        for (int j = i + 1; j < a.Length; j++)
            if (a[i] == a[j]) c++;
    return c;
}

