public int[] TwoSum(int[] nums, int target) {
    var seen = new Dictionary<int, int>();  // number → index
    for (int i = 0; i < nums.Length; i++) {
        // invariant: seen holds exactly nums[0..i-1]
        int need = target - nums[i];
        if (seen.TryGetValue(need, out int j)) return new[] { j, i };
        seen[nums[i]] = i;                  // check first, insert after
    }
    return new int[0];
}

